for n,labels in data.items():
 s=src
 for a,b in zip(orig,labels):s=s.replace(a,b)
 s=s.replace('agent-next-1-workflow-frame-',f'agent-next-{n}-workflow-frame-')
 if n==4:
  s=s.replace('NSPoint(x:867,y:695),NSPoint(x:810,y:695)', 'NSPoint(x:867,y:545),NSPoint(x:810,y:545)')
 if n in (2,3):
  s=s.replace(';arrow(retry)','')
  s=s.replace('if sec>=12&&sec<14{travel(retry,(sec-12)/2)}','')
 s=s.replace('0x137D82',{2:'0xB04749',3:'0x345BC4',4:'0x6852A3',5:'0x307277'}[n])
 path=Path(f'work/agent-next-{n}-workflow.swift');path.write_text(s)
 subprocess.run(['swift',str(path),f'outputs/agent-next-{n}-workflow.gif'],check=True)
